using Beep.OilandGas.Models.Data.Accounting;
using Beep.OilandGas.Models.Data.AccessControl;
using Beep.OilandGas.Models.Data.Company;
using System.Text.Json;
using System.Text.Json.Serialization;
using Beep.OilandGas.Models.Data.ProductionAccounting;
namespace Beep.OilandGas.Accounting.Models;
public sealed record CompanySalesPaymentFacts(string Id,string Number,DateTime Date,decimal Amount,string Currency,string Method,string PayerId,string ExternalReference,string EvidenceReference,string Status,string CreatedBy,DateTime CreatedAtUtc,string NativeRevision)
{
    [JsonIgnore(Condition=JsonIgnoreCondition.WhenWritingNull)]public CompanySalesPaymentReviewSummary? Review{get;init;}
    [JsonIgnore(Condition=JsonIgnoreCondition.WhenWritingNull)]public string? PreparationRevision{get;init;}
}
public sealed record CompanySalesPaymentSource(CompanySalesPostedLedgerReview Ledger,string CustomerId,string Currency,int CurrencyDecimals,decimal OriginalAmount,IReadOnlyList<CompanySalesPaymentFacts> Payments,string Revision)
{
    public const int MaximumPayments=128;
    public static CompanySalesPaymentSource Create(CompanySalesPostedLedgerReview ledger,string customer,string currency,int decimals,decimal amount,IEnumerable<AR_PAYMENT> rows)
    {
        var records=rows.Take(MaximumPayments+1).ToArray();if(records.Length>MaximumPayments || records.Any(row=>row is null))throw new InvalidOperationException("The complete bounded native payment source is unavailable.");foreach(var row in records){var command=CompanySalesPaymentProof.Require(row).Command;if(command.Source.Ledger.Company!=ledger.Company || command.Source.Ledger.BookId!=ledger.BookId || command.Source.Ledger.ReceivableId!=ledger.ReceivableId || command.Source.Currency!=currency)throw new InvalidOperationException("A native payment belongs to another original company/book/receivable/currency.");}
        var facts=records.OrderBy(row=>row.AR_PAYMENT_ID,StringComparer.Ordinal).Select(row=>new CompanySalesPaymentFacts(row.AR_PAYMENT_ID,row.PAYMENT_NUMBER,row.PAYMENT_DATE!.Value,row.PAYMENT_AMOUNT!.Value,row.CURRENCY_CODE,row.PAYMENT_METHOD,row.PAYER_BA_ID,row.EXTERNAL_REFERENCE,row.EVIDENCE_REFERENCE,row.STATUS,row.ROW_CREATED_BY,row.ROW_CREATED_DATE!.Value,ProcessDefinitionRevision.FromJson(JsonSerializer.Serialize(row))){Review=row.REVIEW_WORKFLOW_JSON is null?null:CompanySalesPaymentReviewProof.Require(row).Summary(),PreparationRevision=row.REVIEW_WORKFLOW_JSON is null?null:ProcessDefinitionRevision.FromJson(JsonSerializer.Serialize(CompanySalesPaymentReviewProof.OriginalDraft(row)))}).ToArray();var value=new CompanySalesPaymentSource(CompanyInventorySourceReview.Copy(ledger),customer,currency,decimals,amount,facts,string.Empty);value=value with{Revision=Digest(value)};value.Require(ledger.Company,ledger.ActorUserId,ledger.ReceivableId,ledger.BookId,ledger.CurrencyCode);return CompanyInventorySourceReview.Copy(value);
    }
    public void Require(CompanyScope company,string actor,string receivable,string book,string functionalCurrency)
    {
        if(Ledger is null || Payments is null || Payments.Count>MaximumPayments || Payments.Any(row=>row is null))throw new InvalidOperationException("The complete native payment/posted ledger source is unavailable.");Ledger.Require(company,actor,book,functionalCurrency,receivable);BillingPolicyValues.Text(CustomerId,128);CompanyFxRateReview.Currency(Currency);if(CurrencyDecimals is <0 or >8 || OriginalAmount<=0 || Ledger.Journals.Count!=1)throw new InvalidOperationException("One proven posted ledger and explicit original receivable money/precision are required before a payment proposal.");_=CompanyFxConversion.ExactUnits(OriginalAmount,CurrencyDecimals);var journal=Ledger.Journals.Single();if(journal.Conversion is {} fx){if(Currency!=fx.Rates.SourceCurrency || OriginalAmount!=fx.SourceTotal || CurrencyDecimals!=fx.SourceCurrencyDecimals)throw new InvalidOperationException("The original AR currency/amount differs from its native ledger conversion.");}else if(Currency!=functionalCurrency || OriginalAmount!=journal.Debit)throw new InvalidOperationException("The original AR and same-currency posted ledger money differ.");
        if(Payments.Select(row=>row.Id).Distinct(StringComparer.Ordinal).Count()!=Payments.Count || Payments.Select(row=>row.Number).Distinct(StringComparer.Ordinal).Count()!=Payments.Count || Payments.Select(row=>row.ExternalReference).Distinct(StringComparer.Ordinal).Count()!=Payments.Count || !Payments.SequenceEqual(Payments.OrderBy(row=>row.Id,StringComparer.Ordinal)))throw new InvalidOperationException("The complete native payment identities/order are ambiguous.");
        foreach(var row in Payments){BillingPolicyValues.Intent(row.Id);Values(row.Number,row.Date,row.Amount,CurrencyDecimals,row.Method,row.PayerId,row.ExternalReference,row.EvidenceReference);BillingPolicyValues.Text(row.CreatedBy,128);BillingPolicyValues.Revision(row.NativeRevision);if(row.Currency!=Currency || row.Status is not ("DRAFT" or "APPROVED" or "REJECTED") || row.CreatedAtUtc.Kind!=DateTimeKind.Utc || row.CreatedAtUtc==default)throw new InvalidOperationException("The native payment proposal/status/audit is unconfirmed.");if(row.Status=="DRAFT" && (row.Review is not null || row.PreparationRevision is not null) || row.Status!="DRAFT" && (row.Review is null || !ProcessDefinitionRevision.IsValid(row.PreparationRevision)))throw new InvalidOperationException("The original native payment review/status evidence is unconfirmed.");if(row.Review is {} review){BillingPolicyValues.Intent(review.IntentId);BillingPolicyValues.Text(review.Reviewer,128);BillingPolicyValues.Text(review.FinancialEvidence,2000);BillingPolicyValues.Text(review.ReceiptEvidence,2000);BillingPolicyValues.Text(review.Reason,1000);if(review.Reviewer==row.CreatedBy || review.ReviewedAtUtc.Kind!=DateTimeKind.Utc || review.ReviewedAtUtc<row.CreatedAtUtc || review.Decision!=(row.Status=="APPROVED"?"APPROVE":"REJECT") || review.FinancialDisposition is not ("CONFIRMED" or "ISSUE") || review.ReceiptDisposition is not ("CONFIRMED" or "ISSUE") || review.Decision=="APPROVE" && (review.FinancialDisposition!="CONFIRMED" || review.ReceiptDisposition!="CONFIRMED"))throw new InvalidOperationException("The independent native payment disposition is unconfirmed.");}}
        if(UnreleasedProposedAmount>OriginalAmount || Revision!=Digest(this))throw new InvalidOperationException("The payment source changed or proposed allocations exceed original receivable money.");
    }
    public decimal UnreleasedProposedAmount{get{try{return Payments.Where(row=>row.Status!="REJECTED").Sum(row=>row.Amount);}catch(OverflowException error){throw new InvalidOperationException("The proposed native money exceeds supported capacity.",error);}}}
    public decimal AvailableToPropose=>OriginalAmount-UnreleasedProposedAmount;
    internal static void Values(string number,DateTime date,decimal amount,int decimals,string method,string payer,string reference,string evidence){BillingPolicyValues.Text(number,128);CompanyGLMappingReview.RequireDate(date);if(amount<=0 || method is not ("BANK_TRANSFER" or "ACH" or "WIRE" or "CHECK" or "CASH"))throw new InvalidOperationException("An explicit positive payment amount and supported method are required.");_=CompanyFxConversion.ExactUnits(amount,decimals);BillingPolicyValues.Text(payer,128);BillingPolicyValues.Text(reference,256);BillingPolicyValues.Text(evidence,2000);}
    private static string Digest(CompanySalesPaymentSource value)=>ProcessDefinitionRevision.FromJson(JsonSerializer.Serialize(value with{Revision=string.Empty}));
}
public sealed record CompanySalesPaymentCommand(string IntentId,string Id,CompanySalesPaymentSource Source,string Number,DateTime PaymentDate,decimal Amount,string Method,string PayerId,string ExternalReference,string EvidenceReference,DateTime ObservedAtUtc,string Reason)
{
    public void Require(){ArgumentNullException.ThrowIfNull(Source);Source.Require(Source.Ledger.Company,Source.Ledger.ActorUserId,Source.Ledger.ReceivableId,Source.Ledger.BookId,Source.Ledger.CurrencyCode);BillingPolicyValues.Intent(IntentId);BillingPolicyValues.Intent(Id);BillingPolicyValues.Text(Reason,128);CompanySalesPaymentSource.Values(Number,PaymentDate,Amount,Source.CurrencyDecimals,Method,PayerId,ExternalReference,EvidenceReference);if(ObservedAtUtc.Kind!=DateTimeKind.Utc || ObservedAtUtc==default || Source.Payments.Count>=CompanySalesPaymentSource.MaximumPayments || Amount>Source.AvailableToPropose || Source.Payments.Any(row=>row.Id==Id || row.Number==Number || row.ExternalReference==ExternalReference))throw new InvalidOperationException("Original UTC observation, unreserved payment identity/reference and an exact available proposal amount are required. Overpayment is not clamped.");if(JsonSerializer.Serialize(this).Length>CompanySalesPaymentProof.MaximumLength/2)throw new InvalidOperationException("The complete original payment source/request exceeds native receipt capacity.");}
    public AR_PAYMENT CreateRow()=>new(){AR_PAYMENT_ID=Id,AR_INVOICE_ID=Source.Ledger.ReceivableId,PAYMENT_NUMBER=Number,PAYMENT_DATE=PaymentDate,PAYMENT_AMOUNT=Amount,PAYMENT_METHOD=Method,CHECK_NUMBER=Method=="CHECK"?ExternalReference:null!,OWNER_TENANT_ID=Source.Ledger.Company.TenantId,OWNER_COMPANY_BA_ID=Source.Ledger.Company.BusinessAssociateId,BOOK_ID=Source.Ledger.BookId,FIELD_ID=Source.Ledger.FieldId,CURRENCY_CODE=Source.Currency,PAYER_BA_ID=PayerId,EXTERNAL_REFERENCE=ExternalReference,EVIDENCE_REFERENCE=EvidenceReference,STATUS="DRAFT",SOURCE_REVISION=Source.Revision,ACTIVE_IND="Y",SOURCE=CompanySalesPaymentProof.NativeSource,REMARK=Reason,PPDM_GUID=Guid.ParseExact(IntentId,"N").ToString()};
    public void RequireCurrent(CompanySalesPaymentSource current){Require();current.Require(Source.Ledger.Company,Source.Ledger.ActorUserId,Source.Ledger.ReceivableId,Source.Ledger.BookId,Source.Ledger.CurrencyCode);if(JsonSerializer.Serialize(current)!=JsonSerializer.Serialize(Source))throw new InvalidOperationException("The complete original payment/posted source changed. Retain the original request.");}
}
public sealed record CompanySalesPaymentReceipt(CompanySalesPaymentCommand Command,string RowRevision);
public static class CompanySalesPaymentProof
{
    public const int MaximumLength=1048576;
    public const string NativeSource="COMPANY_SALES_PAYMENT_DRAFT";
    public static string Create(CompanySalesPaymentCommand command,AR_PAYMENT row){RequireFacts(command,row);var json=JsonSerializer.Serialize(new CompanySalesPaymentReceipt(command,Digest(row)));if(json.Length>MaximumLength)throw new InvalidOperationException("The complete native payment receipt exceeds capacity.");return json;}
    public static CompanySalesPaymentReceipt Require(AR_PAYMENT row){if(row.REVIEW_WORKFLOW_JSON is not null)row=CompanySalesPaymentReviewProof.OriginalDraft(row);if(string.IsNullOrWhiteSpace(row.PREPARATION_WORKFLOW_JSON) || row.PREPARATION_WORKFLOW_JSON.Length>MaximumLength)throw new InvalidOperationException("The original native company payment receipt is unavailable.");var value=JsonSerializer.Deserialize<CompanySalesPaymentReceipt>(row.PREPARATION_WORKFLOW_JSON) ??throw new InvalidOperationException("The native payment receipt is malformed.");if(value.Command is null)throw new InvalidOperationException("The original payment command is unavailable.");RequireFacts(value.Command,row);if(value.RowRevision!=Digest(row))throw new InvalidOperationException("The complete original payment proposal changed.");return value;}
    private static void RequireFacts(CompanySalesPaymentCommand command,AR_PAYMENT row){command.Require();CompanyGLAccountReview.RequireAudit(row);var expected=command.CreateRow();expected.ROW_CREATED_BY=row.ROW_CREATED_BY;expected.ROW_CREATED_DATE=row.ROW_CREATED_DATE;expected.ROW_CHANGED_BY=row.ROW_CHANGED_BY;expected.ROW_CHANGED_DATE=row.ROW_CHANGED_DATE;var actual=CompanyInventorySourceReview.Copy(row);actual.PREPARATION_WORKFLOW_JSON=null!;if(row.ROW_CREATED_BY!=command.Source.Ledger.ActorUserId || row.ROW_CHANGED_DATE is not null && row.ROW_CHANGED_BY!=command.Source.Ledger.ActorUserId || command.ObservedAtUtc>row.ROW_CREATED_DATE || JsonSerializer.Serialize(expected)!=JsonSerializer.Serialize(actual))throw new InvalidOperationException("Only the exact original payment proposal and native producer audit are authorized.");}
    private static string Digest(AR_PAYMENT row){var copy=CompanyInventorySourceReview.Copy(row);copy.PREPARATION_WORKFLOW_JSON=null!;return ProcessDefinitionRevision.FromJson(JsonSerializer.Serialize(copy));}
}
